ducto" variant="outlined" density="comfortable" class="purchase-line-product" @update:model-value="setProductPrice(line)"/><v-text-field v-model="line.cantidad" label="Cantidad" type="number" min="0.001" step="0.001" variant="outlined" density="comfortable"/><v-text-field v-model="line.precioUnitario" label="Precio unitario" prefix="S/" type="number" min="0.0001" step="0.0001" variant="outlined" density="comfortable"/><v-btn icon="mdi-delete-outline" color="error" variant="text" @click="lines.splice(index,1)"/></div><div class="text-end">Subtotal: <strong>{{ money(lineTotal(line)) }}</strong></div></div><v-row class="mt-2"><v-col cols="12" md="7"><v-checkbox v-model="form.hasVoucher" label="Registrar comprobante" color="primary" hide-details/><v-row v-if="form.hasVoucher"><v-col cols="12" sm="4"><v-select v-model="form.voucherType" :items="voucherTypes" item-title="nombre" item-value="idTipoComprobante" label="Tipo" variant="outlined"/></v-col><v-col cols="6" sm="4"><v-text-field v-model="form.series" label="Serie" variant="outlined"/></v-col><v-col cols="6" sm="4"><v-text-field v-model="form.number" label="Número" variant="outlined"/></v-col><v-col cols="12"><v-text-field v-model="form.issueDate" type="date" label="Fecha de emisión" variant="outlined"/></v-col></v-row><PagosEditor v-model="payments" :medios="paymentMethods"/></v-col><v-col cols="12" md="5"><v-card color="primary" variant="tonal" rounded="lg"><v-card-text><div class="d-flex"><span>Total compra</span><v-spacer/><strong class="text-h6">{{ money(purchaseTotal) }}</strong></div><div class="d-flex mt-2"><span>Pago inicial</span><v-spacer/><strong>{{ money(paymentTotal) }}</strong></div><v-divider class="my-2"/><div class="d-flex"><span>Saldo pendiente</span><v-spacer/><strong>{{ money(Math.max(0,purchaseTotal-paymentTotal)) }}</strong></div></v-card-text></v-card></v-col></v-row></v-card-text><v-divider/><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="dialog=false">Cancelar</v-btn><v-btn color="primary" :loading="saving" @click="save">Registrar compra</v-btn></v-card-actions></v-card></v-dialog>

    <ReconocerProductoDialog v-if="recognitionDialog" v-model="recognitionDialog" :id-sucursal="branch.idSucursalActual" precio="compra" :validar-seleccion="visualSelectionIssue" @seleccionar="addVisualProduct" />
