    <v-dialog v-model="perceptionDialog" max-width="680" persistent><v-card rounded="xl"><v-card-title class="operaciones-dialog-title"><span class="operaciones-dialog-icon"><v-icon>mdi-percent-outline</v-icon></span>Percepción de compra #{{ actionPurchase?.idCompra }}</v-card-title><v-card-text class="pa-5"><v-alert v-if="formError" type="error" variant="tonal" class="mb-4">{{ formError }}</v-alert><v-row><v-col cols="12" sm="6"><v-text-field v-model="perception.date" type="date" label="Fecha" variant="outlined"/></v-col><v-col cols="12" sm="6"><v-text-field v-model="perception.certificate" label="N.º constancia" variant="outlined"/></v-col><v-col cols="12" sm="4"><v-text-field v-model="perception.base" label="Base" prefix="S/" type="number" variant="outlined"/></v-col><v-col cols="12" sm="4"><v-text-field v-model="perception.percent" label="Porcentaje" suffix="%" type="number" variant="outlined"/></v-col><v-col cols="12" sm="4"><v-text-field :model-value="perceptionAmount.toFixed(2)" label="Monto" prefix="S/" readonly variant="outlined"/></v-col></v-row><PagosEditor v-model="actionPayments" :medios="paymentMethods"/></v-card-text><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="perceptionDialog=false">Cancelar</v-btn><v-btn color="primary" :loading="saving" @click="savePerception">Registrar percepción</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!selected" max-width="800" @update:model-value="selected=null"><v-card v-if="selected" rounded="xl"><v-card-title class="pa-5">Compra #{{ selected.idCompra }}</v-card-title><v-card-text class="px-5 pb-5"><div class="mb-4"><strong>{{ selected.nombreProveedor }}</strong><div class="text-body-2 text-medium-emphasis">{{ selected.almacen.nombre }} · {{ dateTime(selected.fechaCompra) }}</div></div><v-table density="compact"><thead><tr><th>Producto</th><th>Cantidad</th><th>P. unitario</th><th class="text-end">Subtotal</th></tr></thead><tbody><tr v-for="d in selected.detalles" :key="d.idCompraDetalle"><td>{{ d.productoSucursal.producto.nombre }}</td><td>{{ d.cantidad }}</td><td>{{ money(d.precioUnitario) }}</td><td class="text-end">{{ money(Number(d.cantidad)*Number(d.precioUnitario)) }}</td></tr></tbody></v-table><div class="d-flex justify-end ga-6 mt-4"><span>Pagado: <strong>{{ money(selected.montoPagado) }}</strong></span><span>Saldo: <strong>{{ money(selected.saldoPendiente) }}</strong></span><span>Total: <strong>{{ money(selected.total) }}</strong></span></div></v-card-text><v-card-actions><v-spacer/><v-btn variant="text" color="primary" @click="selected=null">Cerrar</v-btn></v-card-actions></v-card></v-dialog><v-snackbar v-model="notice" color="success">Operación registrada correctamente</v-snackbar>
  </div>
</template>
<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { getApiErrorMessage } from '@/core/api/api-error'
import { mediosPagoApi, personasApi } from '@/core/api/administracion.api'
import { Permiso } from '@/core/constants/permisos'
import type { MedioPago, PersonaRegistro } from '@/core/types/administracion.types'
import { useAuthStore } from '@/modules/auth/auth.store'
import { almacenesApi, productoSucursalApi } from '@/modules/logistica/logistica.api'
import type { Almacen, Pagina, ProductoSucursal } from '@/modules/logistica/logistica.types'
import { useSucursalStore } from '@/shared/stores/sucursal.store'
import ReconocerProductoDialog from '@/modules/reconocimiento/components/ReconocerProductoDialog.vue'
import type { CandidatoVisual, SeleccionVisual } from '@/modules/reconocimiento/reconocimiento.types'
import { validarCantidad } from '@/modules/reconocimiento/imagen'
import PagosEditor from '../components/PagosEditor.vue'
import { cajasApi, cargarTodo, comprasApi, tiposComprobanteApi } from '../operaciones.api'
import type { Caja, Compra, PagoPayload, TipoComprobante } from '../operaciones.types'
import '../operaciones.css'
import { useRegistroDesdeCaja } from '../useRegistroDesdeCaja'
interface Line{idProductoSucursal:number|null;cantidad:string;precioUnitario:string}
const recognitionDialog = ref(false)
const formLoading = ref(false)
let formRequest = 0
const auth=useAuthStore(),branch=useSucursalStore(),canManage=computed(()=>auth.puede(Permiso.COMPRAS_GESTIONAR)),items=ref<Compra[]>([]),selected=ref<Compra|null>(null),actionPurchase=ref<Compra|null>(null),openBox=ref<Caja|null>(null),products=ref<ProductoSucursal[]>([]),warehouses=ref<Almacen[]>([]),providers=ref<PersonaRegistro[]>([]),paymentMethods=ref<MedioPago[]>([]),voucherTypes=ref<TipoComprobante[]>([]),lines=ref<Line[]>([]),payments=ref<PagoPayload[]>([]),actionPayments=ref<PagoPayload[]>([]),search=ref(''),page=ref(1),limit=30,total=ref(0),loading=ref(false),saving=ref(false),dialog=ref(false),paymentDialog=ref(false),perceptionDialog=ref(false),error=ref(''),formError=ref(''),notice=ref(false),actionDetail=ref(''),form=reactive({providerId:null as number|null,providerName:'',warehouseId:null as number|null,date:'',hasVoucher:false,voucherType:null as number|null,series:'',number:'',issueDate:''}),perception=reactive({date:new Date().toISOString().slice(0,10),certificate:'',base:'',percent:'2'})
const purchaseTotal=computed(()=>lines.value.reduce((s,x)=>s+lineTotal(x),0)),paymentTotal=computed(()=>payments.value.reduce((s,x)=>s+Number(x.monto||0),0)),actionPaymentTotal=computed(()=>actionPayments.value.reduce((s,x)=>s+Number(x.monto||0),0)),perceptionAmount=computed(()=>Math.round((Number(perception.base)||0)*(Number(perception.percent)||0))/100)
let listRequest=0
async function load(){
  const idSucursal=branch.idSucursalActual,current=++listRequest
  if(!idSucursal){items.value=[];total.value=0;openBox.value=null;loading.value=false;return}
  loading.value=true;error.value='';openBox.value=null
  try {
    const [response,box]=await Promise.all([comprasApi.listar({idSucursal,pagina:page.value,limite:limit,buscar:search.value.trim()||undefined}),cajasApi.abierta(idSucursal).catch(()=>null)])
    if(current!==listRequest)return
    items.value=response.data.data;total.value=response.data.total;openBox.value=box?.data??null
  }catch(cause){if(current===listRequest)error.value=getApiErrorMessage(cause,'No se pudieron cargar las compras')}
  finally{if(current===listRequest)loading.value=false}
}
async function formData(){
  const idSucursal=branch.idSucursalActual,current=++formRequest
  if(!idSucursal)return
  formLoading.value=true;products.value=[]
  try {
    const [p,w,pr,m,t]=await Promise.all([paginasCatalogo(pagina=>productoSucursalApi.listar({idSucursal,estado:true,pagina,limite:100})),paginasCatalogo(pagina=>almacenesApi.listar({idSucursal,estado:true,pagina,limite:100})),personasApi.listar('PROVEEDOR'),mediosPagoApi.listar(),cargarTodo(tiposComprobanteApi.listar)])
    if(current!==formRequest||branch.idSucursalActual!==idSucursal||!dialog.value)return
    products.value=p.filter(x=>x.producto.estado);warehouses.value=w;providers.value=pr.data.filter(x=>x.activo);paymentMethods.value=m.data;voucherTypes.value=t
  }finally{if(current===formRequest)formLoading.value=false}
}
async function paginasCatalogo<T>(fetchPage:(pagina:number)=>Promise<{data:Pagina<T>}>){
  const values:T[]=[];let pagina=1,total=0
  do{const response=await fetchPage(pagina++);values.push(...response.data.data);total=response.data.total;if(!response.data.data.length)break}while(values.length<total)
  return values
}
async function openCreate(){Object.assign(form,{providerId:null,providerName:'',warehouseId:null,date:'',hasVoucher:false,voucherType:null,series:'',number:'',issueDate:''});lines.value=[];payments.value=[];addLine();formError.value='';dialog.value=true;const idSucursal=branch.idSucursalActual;try{await formData()}catch(cause){if(dialog.value&&branch.idSucursalActual===idSucursal)formError.value=getApiErrorMessage(cause)}}
function addLine(){lines.value.push({idProductoSucursal:null,cantidad:'1',precioUnitario:''})}function availableProducts(i:number){const used=new Set(lines.value.filter((_,x)=>x!==i).map(x=>x.idProductoSucursal));return products.value.filter(x=>!used.has(x.idProductoSucursal))}function setProductPrice(line:Line){const p=products.value.find(x=>x.idProductoSucursal===line.idProductoSucursal);if(p)line.precioUnitario=p.precioCompra}function lineTotal(line:Line){return(Number(line.cantidad)||0)*(Number(line.precioUnitario)||0)}function selectProvider(id:number|null){const p=providers.value.find(x=>x.id===id);if(p)form.providerName=p.nombre}
async function save(){if(saving.value)return;if(!openBox.value||!branch.idSucursalActual)return;if(!form.providerName.trim()||!form.warehouseId){formError.value='Completa proveedor y almacén';return}if(!lines.value.length||lines.value.some(x=>!x.idProductoSucursal||lineTotal(x)<=0)){formError.value='Completa correctamente los productos';return}if(paymentTotal.value>purchaseTotal.value+.001){formError.value='El pago inicial no puede superar el total';return}if(form.hasVoucher&&(!form.voucherType||!form.series.trim()||!form.number.trim()||!form.issueDate)){formError.value='Completa el comprobante';return}saving.value=true;formError.value='';try{await comprasApi.crear({idCaja:openBox.value.idCaja,idSucursal:branch.idSucursalActual,idAlmacen:form.warehouseId,idProveedor:form.providerId??undefined,nombreProveedor:form.providerName.trim(),fechaCompra:toIso(form.date),total:purchaseTotal.value.toFixed(2),detalles:lines.value.map(x=>({idProductoSucursal:x.idProductoSucursal,cantidad:Number(x.cantidad).toFixed(3),precioUnitario:Number(x.precioUnitario).toFixed(4)})),pagos:payments.value,...(form.hasVoucher?{comprobante:{idTipoComprobante:form.voucherType,serie:form.series.trim(),numero:form.number.trim(),fechaEmision:form.issueDate}}:{})});dialog.value=false;notice.value=true;await load()}catch(cause){formError.value=getApiErrorMessage(cause,'No se pudo registrar la compra')}finally{saving.value=false}}
async function ensurePayments(){if(!paymentMethods.value.length)paymentMethods.value=(await mediosPagoApi.listar()).data}async function openPayment(item:Compra){actionPurchase.value=item;actionPayments.value=[];actionDetail.value='';formError.value='';paymentDialog.value=true;await ensurePayments()}async function savePayment(){if(saving.value)return;if(!actionPurchase.value||!openBox.value||!branch.idSucursalActual||actionPaymentTotal.value<=0){formError.value='Agrega al menos un pago';return}if(actionPaymentTotal.value>Number(actionPurchase.value.saldoPendiente)+.001){formError.value='El pago supera el saldo pendiente';return}saving.value=true;try{await comprasApi.pagar(actionPurchase.value.idCompra,{idCaja:openBox.value.idCaja,idSucursal:branch.idSucursalActual,monto:actionPaymentTotal.value.toFixed(2),detalle:actionDetail.value.trim()||undefined,pagos:actionPayments.value});paymentDialog.value=false;notice.value=true;await load()}catch(cause){formError.value=getApiErrorMessage(cause)}finally{saving.value=false}}
async function openPerception(item:Compra){actionPurchase.value=item;actionPayments.value=[];Object.assign(perception,{date:new Date().toISOString().slice(0,10),certificate:'',base:item.total,percent:'2'});formError.value='';perceptionDialog.value=true;await ensurePayments()}async function savePerception(){if(saving.value)return;if(!actionPurchase.value||!openBox.value||!branch.idSucursalActual||perceptionAmount.value<=0){formError.value='Completa los datos de percepción';return}if(Math.abs(actionPaymentTotal.value-perceptionAmount.value)>.001){formError.value='La distribución debe coincidir con el monto de percepción';return}saving.value=true;try{await comprasApi.percepcion(actionPurchase.value.idCompra,{idCaja:openBox.value.idCaja,idSucursal:branch.idSucursalActual,fechaPercepcion:perception.date,baseCalculo:Number(perception.base).toFixed(2),porcentaje:Number(perception.percent).toFixed(3),monto:perceptionAmount.value.toFixed(2),numeroConstancia:perception.certificate.trim()||undefined,pagos:actionPayments.value});perceptionDialog.value=false;notice.value=true;await load()}catch(cause){formError.value=getApiErrorMessage(cause)}finally{saving.value=false}}
async function showDetail(item:Compra){try{selected.value=(await comprasApi.obtener(item.idCompra)).data}catch(cause){error.value=getApiErrorMessage(cause)}}function voucher(x:Compra){return x.comprobante?`${x.comprobante.serie}-${x.comprobante.numero}`:'—'}function searchNow(){if(page.value!==1)page.value=1;else void load()}function toIso(v:string){return v?new Date(v).toISOString():undefined}function money(v:string|number){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(Number(v)||0)}function dateTime(v:string){return new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(v))}
function visualSelectionIssue(candidate:CandidatoVisual,cantidad:number){
  if(!dialog.value||saving.value||formLoading.value||!canManage.value||!openBox.value)return 'La compra no está disponible para edición.'
  if(!products.value.some(item=>item.idProductoSucursal===candidate.idProductoSucursal&&item.idProducto===candidate.idProducto))return 'Este producto no está disponible. Vuelve a abrir la compra para actualizar el catálogo.'
  const existing=lines.value.find(line=>line.idProductoSucursal===candidate.idProductoSucursal)
  if(existing&&validarCantidad(existing.cantidad))return 'Corrige la cantidad del producto que ya está en la compra antes de agregar más.'
  if(cantidad+Number(existing?.cantidad||0)>99999999999.999)return 'La cantidad total supera el máximo permitido.'
  return ''
}
function addVisualProduct({candidato,cantidad}:SeleccionVisual){
  const issue=visualSelectionIssue(candidato,cantidad)
  if(issue){formError.value=issue;return}
  if(!Number.isFinite(cantidad)||cantidad<=0)return
  const existing=lines.value.find(line=>line.idProductoSucursal===candidato.idProductoSucursal)
  if(existing)existing.cantidad=(Number(existing.cantidad)+cantidad).toFixed(3)
  else {const empty=lines.value.find(line=>!line.idProductoSucursal);const data={idProductoSucursal:candidato.idProductoSucursal,cantidad:cantidad.toFixed(3),precioUnitario:candidato.precioCompra};if(empty)Object.assign(empty,data);else lines.value.push(data)}
  recognitionDialog.value=false
}
watch([()=>branch.idSucursalActual,page],()=>void load(),{immediate:true})
watch(()=>branch.idSucursalActual,()=>{recognitionDialog.value=false;dialog.value=false;paymentDialog.value=false;perceptionDialog.value=false;selected.value=null;formRequest++;formLoading.value=false;products.value=[]})
watch([dialog,()=>form.warehouseId,saving],()=>{recognitionDialog.value=false})
useRegistroDesdeCaja(openBox,loading,canManage,error,openCreate)
</script>
